import React, { createContext, useContext, useState, useEffect } from 'react';
import api from '../utils/api';

const AuthContext = createContext(null);

export const AuthProvider = ({ children }) => {
  const [user,    setUser]    = useState(null);
  const [loading, setLoading] = useState(true);  // Page load pe token check karne tak true rehta hai

  // App open hone pe check karo — kya pehle se logged in hai?
  useEffect(() => {
    const token = localStorage.getItem('gymToken');
    const saved = localStorage.getItem('gymUser');
    if (token && saved) {
      setUser(JSON.parse(saved));
      // Server se fresh data lo
      api.get('/auth/me')
        .then(res => {
          setUser(res.data);
          localStorage.setItem('gymUser', JSON.stringify(res.data));
        })
        .catch(() => {
          localStorage.removeItem('gymToken');
          localStorage.removeItem('gymUser');
          setUser(null);
        })
        .finally(() => setLoading(false));
    } else {
      setLoading(false);
    }
  }, []);

  // Login function
  const login = async (email, password) => {
    const res = await api.post('/auth/login', { email, password });
    localStorage.setItem('gymToken', res.data.token);
    localStorage.setItem('gymUser', JSON.stringify(res.data.user));
    setUser(res.data.user);
    return res.data;
  };

  // Logout function
  const logout = () => {
    localStorage.removeItem('gymToken');
    localStorage.removeItem('gymUser');
    setUser(null);
    window.location.href = '/';
  };

  // User data server se refresh karo
  const refreshUser = async () => {
    const res = await api.get('/auth/me');
    setUser(res.data);
    localStorage.setItem('gymUser', JSON.stringify(res.data));
  };

  return (
    <AuthContext.Provider value={{ user, loading, login, logout, refreshUser }}>
      {children}
    </AuthContext.Provider>
  );
};

// Custom hook — kisi bhi component mein use karo
export const useAuth = () => useContext(AuthContext);
